def count_up_to(limit):
    n = 1
    while n <= limit:
        yield n
        n += 1

def shout(text):
    return text.upper()

say = shout
print(say("hi"))   # HI

@timer
def slow_add(a, b):
    return a + b

def timer(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        result = func(*args, **kwargs)
        return result
    return wrapper
